/**
 * PDF-export
 * 精美 PDF 导出：MarkdownRenderer 忠实渲染 + 仓库样式收集
 * + Paged.js 分页引擎 + 隐藏窗口静默打印。
 *
 * 无构建步骤：本文件为纯 JavaScript，可直接修改。
 * 迭代入口：presets/ 目录下的 CSS 决定排版气质。
 */

const {
  Plugin,
  MarkdownRenderer,
  Component,
  Modal,
  Notice,
  PluginSettingTab,
  Setting,
} = require('obsidian');
const fs = require('fs');
const path = require('path');
/* ---------- CSS 消毒（原 css-sanitize.js，内联以避免相对 require 在某些加载器下失败） ----------
 * 让收集来的 Obsidian 样式安全通过 Paged.js 0.4.x：
 * 1. 丢弃选择器含"函数式伪类内逗号"的规则（:is/:where/:not/:has…）；
 * 2. 整块丢弃 @media print（打印排版由插件 @page 体系接管）；
 * 3. 递归处理 @media/@supports/@layer/@container 嵌套块。
 */
const POISON_SELECTOR = /:(?:is|where|not|matches|any|has)\([^()]*,/i;

function stripComments(css) {
  return css.replace(/\/\*[\s\S]*?\*\//g, '');
}

function sanitizeCssForPagedjs(css) {
  css = stripComments(css);
  const out = [];
  const n = css.length;
  let i = 0;
  let buf = '';

  const takeString = (sink) => {
    const q = css[i];
    sink += css[i];
    i++;
    while (i < n) {
      if (css[i] === '\\') {
        sink += css[i] + (css[i + 1] || '');
        i += 2;
        continue;
      }
      sink += css[i];
      if (css[i] === q) {
        i++;
        break;
      }
      i++;
    }
    return sink;
  };

  while (i < n) {
    const ch = css[i];
    if (ch === '"' || ch === "'") {
      buf = takeString(buf);
      continue;
    }
    if (ch === '{') {
      /* 找到配对的闭括号 */
      let depth = 1;
      let j = i + 1;
      let body = '';
      while (j < n) {
        const c = css[j];
        if (c === '"' || c === "'") {
          /* 字符串里的花括号不算 */
          const q = c;
          body += c;
          j++;
          while (j < n) {
            if (css[j] === '\\') {
              body += css[j] + (css[j + 1] || '');
              j += 2;
              continue;
            }
            body += css[j];
            if (css[j] === q) {
              j++;
              break;
            }
            j++;
          }
          continue;
        }
        if (c === '{') depth++;
        else if (c === '}') {
          depth--;
          if (depth === 0) break;
        }
        body += c;
        j++;
      }
      const prelude = buf.trim();
      buf = '';
      if (/^@media\s+print/i.test(prelude)) {
        /* 丢弃整块 */
      } else if (POISON_SELECTOR.test(prelude)) {
        /* 丢弃毒规则 */
      } else if (/^@(media|supports|layer|container|scope)/i.test(prelude)) {
        out.push(prelude + '{' + sanitizeCssForPagedjs(body) + '}');
      } else {
        out.push(prelude + '{' + body + '}');
      }
      i = j + 1;
    } else if (ch === ';') {
      buf += ch;
      i++;
      const prelude = buf.trim();
      if (prelude && !POISON_SELECTOR.test(prelude)) out.push(prelude);
      buf = '';
    } else {
      buf += ch;
      i++;
    }
  }
  const tail = buf.trim();
  if (tail) out.push(tail);
  return out.join('\n');
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const PRESETS = [
  {
    id: 'report',
    name: '正式报告',
    desc: '封面 + 目录 + 页眉页码，A4 正式文档',
  },
  {
    id: 'snapshot',
    name: '预览快照',
    desc: '还原 Obsidian 阅读视图的排版气质',
  },
  {
    id: 'compact',
    name: '紧凑打印',
    desc: '小字号密排，省纸可读',
  },
];

const DEFAULT_SETTINGS = {
  preset: 'report',
  author: '', // 封面署名，留空则不显示；建议在设置中填写
  brand: 'J · STUDIO', // 封面右下角品牌文字
  cover: true,
  toc: true,
  header: true,
  pageNumbers: true,
  openAfter: true,
  outputMode: 'ask', // 'ask' | 'note-folder'
  customCss: '',
};

/* ==== EMBEDDED-ASSETS:BEGIN（由 tools/embed-assets.js 生成，请勿手改） ==== */
/* 商店安装只包含 main.js / manifest.json / styles.css，
   presets 与 Paged.js 引擎必须以 base64 内嵌于此作为兜底；
   开发态仍优先读取 presets/ 与 vendor/ 真实文件，便于直接改 CSS 迭代。 */
const EMBEDDED_ASSETS = { presetsB64: {"_base.css":"","compact.css":"","report.css":"","snapshot.css":""}, pagedPolyfillB64: "" };
/* ==== EMBEDDED-ASSETS:END ==== */

/* ---------- 小工具 ---------- */

/* 内嵌资产解码（base64 → utf8 文本）。
   用 base64 是因为引擎源码里的个别字符（U+2028 行分隔符等）
   无法安全进入 JS 字符串字面量 */
function decodeEmbeddedText(b64) {
  if (!b64) return '';
  try {
    return require('buffer').Buffer.from(b64, 'base64').toString('utf8');
  } catch (e) {
    return '';
  }
}

function embeddedPresetText(name) {
  const table = EMBEDDED_ASSETS.presetsB64 || {};
  return decodeEmbeddedText(table[name]);
}

function escapeHtml(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function electronRemote() {
  try {
    if (window.electron && window.electron.remote) return window.electron.remote;
    const e = window.require('electron');
    if (e && e.remote) return e.remote;
  } catch (err) {
    /* noop */
  }
  return null;
}

function fileUrl(p) {
  return 'file:///' + encodeURI(path.resolve(p).split(path.sep).join('/'));
}

function mimeOf(p) {
  const ext = path.extname(p).toLowerCase();
  const map = {
    '.png': 'image/png',
    '.jpg': 'image/jpeg',
    '.jpeg': 'image/jpeg',
    '.gif': 'image/gif',
    '.webp': 'image/webp',
    '.svg': 'image/svg+xml',
    '.bmp': 'image/bmp',
    '.avif': 'image/avif',
    '.tiff': 'image/tiff',
    '.tif': 'image/tiff',
  };
  return map[ext] || 'application/octet-stream';
}

function hexToRgbTriplet(hex) {
  const m = hex.trim().replace('#', '');
  if (m.length === 3) {
    return [
      parseInt(m[0] + m[0], 16),
      parseInt(m[1] + m[1], 16),
      parseInt(m[2] + m[2], 16),
    ].join(', ');
  }
  if (m.length === 6 || m.length === 8) {
    return [
      parseInt(m.slice(0, 2), 16),
      parseInt(m.slice(2, 4), 16),
      parseInt(m.slice(4, 6), 16),
    ].join(', ');
  }
  return null;
}

/* ---------- 导出选项弹窗 ---------- */

class JXExportModal extends Modal {
  constructor(plugin) {
    super(plugin.app);
    this.plugin = plugin;
    this.s = {
      preset: plugin.settings.preset,
      cover: plugin.settings.cover,
      toc: plugin.settings.toc,
      header: plugin.settings.header,
      pageNumbers: plugin.settings.pageNumbers,
    };
    this._toggleRefs = [];
  }

  onOpen() {
    this.contentEl.empty();
    this.contentEl.addClass('jx-modal');

    /* 只约束 .modal 本体；containerEl 是全屏遮罩，动它会破坏布局 */
    this.modalEl.style.maxHeight = 'min(90vh, 800px)';
    this.modalEl.style.height = 'auto';
    this.modalEl.style.overflowX = 'hidden';
    this.modalEl.style.overflowY = 'auto';
    this.modalEl.addClass('jx-modal-root');

    const head = this.contentEl.createEl('div', 'jx-modal-head');
    const headText = head.createEl('div', 'jx-modal-head-text');
    headText.createEl('div', {
      text: 'PDF-export · 精美导出',
      cls: 'jx-modal-title',
    });
    headText.createEl('div', {
      text: '以 Paged.js 分页引擎输出，页码、页眉、目录由排版引擎生成。',
      cls: 'jx-modal-sub',
    });

    /* 操作按钮放顶部，保证任何布局下都可见 */
    const actions = head.createEl('div', 'jx-modal-actions');
    const btnPdf = actions.createEl('button', {
      text: '导出 PDF',
      cls: 'mod-cta',
    });
    btnPdf.onclick = () => {
      this.close();
      this.plugin.runExport('pdf', this.s);
    };
    const btnHtml = actions.createEl('button', { text: '导出 HTML' });
    btnHtml.onclick = () => {
      this.close();
      this.plugin.runExport('html', this.s);
    };

    /* 预设卡片 */
    const grid = this.contentEl.createEl('div', 'jx-preset-grid');
    for (const p of PRESETS) {
      const card = grid.createEl('div', 'jx-preset-card');
      if (p.id === this.s.preset) card.addClass('is-active');
      card.createEl('div', { text: p.name, cls: 'jx-preset-name' });
      card.createEl('div', { text: p.desc, cls: 'jx-preset-desc' });
      card.onclick = () => {
        this.s.preset = p.id;
        grid.querySelectorAll('.jx-preset-card').forEach((el) =>
          el.removeClass('is-active')
        );
        card.addClass('is-active');
        this._refreshToggles();
      };
    }

    /* 元素开关：紧凑网格，避免纵向过高被裁切 */
    const togglesEl = this.contentEl.createEl('div', 'jx-toggle-grid');
    const mk = (key, name, desc) => {
      const cell = togglesEl.createEl('div', 'jx-toggle-cell');
      const st = new Setting(cell)
        .setName(name)
        .setDesc(desc)
        .addToggle((tg) => {
          tg.setValue(this.s[key]).onChange((v) => {
            this.s[key] = v;
          });
          this._toggleRefs.push({ key, st, tg });
        });
      return st;
    };
    mk('cover', '封面页', '正式报告封面');
    mk('toc', '目录页', '含真实页码');
    mk('header', '页眉', '标题与细线');
    mk('pageNumbers', '页码', '页脚居中');

    this._refreshToggles();
  }

  _refreshToggles() {
    const isReport = this.s.preset === 'report';
    for (const { key, st, tg } of this._toggleRefs) {
      const relevant = key === 'pageNumbers' ? true : isReport;
      st.setDisabled(!relevant);
      st.settingEl.toggleClass('is-disabled', !relevant);
    }
  }
}

/* ---------- 设置页 ---------- */

class JXSettingTab extends PluginSettingTab {
  constructor(app, plugin) {
    super(app, plugin);
    this.plugin = plugin;
  }

  display() {
    const { containerEl } = this;
    containerEl.empty();

    new Setting(containerEl)
      .setName('默认预设')
      .setDesc('打开导出弹窗时选中的预设')
      .addDropdown((dd) => {
        for (const p of PRESETS) dd.addOption(p.id, p.name);
        dd.setValue(this.plugin.settings.preset).onChange(async (v) => {
          this.plugin.settings.preset = v;
          await this.plugin.saveSettings();
        });
      });

    new Setting(containerEl)
      .setName('作者名')
      .setDesc('用于封面署名')
      .addText((tx) => {
        tx.setValue(this.plugin.settings.author).onChange(async (v) => {
          this.plugin.settings.author = v;
          await this.plugin.saveSettings();
        });
      });

    new Setting(containerEl)
      .setName('输出位置')
      .addDropdown((dd) => {
        dd.addOption('ask', '每次询问（另存为对话框）');
        dd.addOption('note-folder', '直接写入笔记所在文件夹');
        dd.setValue(this.plugin.settings.outputMode).onChange(async (v) => {
          this.plugin.settings.outputMode = v;
          await this.plugin.saveSettings();
        });
      });

    new Setting(containerEl)
      .setName('导出后自动打开')
      .addToggle((tg) => {
        tg.setValue(this.plugin.settings.openAfter).onChange(async (v) => {
          this.plugin.settings.openAfter = v;
          await this.plugin.saveSettings();
        });
      });

    new Setting(containerEl)
      .setName('自定义 CSS')
      .setDesc('追加在所有预设之后，优先级最高。可覆盖任何排版细节。')
      .addTextArea((ta) => {
        ta.setValue(this.plugin.settings.customCss).onChange(async (v) => {
          this.plugin.settings.customCss = v;
          await this.plugin.saveSettings();
        });
        ta.inputEl.rows = 8;
        ta.inputEl.addClass('jx-css-editor');
      });

    containerEl.createEl('div', {
      text: `预设文件位于 ${this.plugin.pluginDir} 的 presets/ 目录，可直接编辑 CSS 迭代排版。`,
      cls: 'jx-setting-note',
    });
  }
}

/* ---------- 插件主体 ---------- */

module.exports = class JStudioExportPlugin extends Plugin {
  async onload() {
    await this.loadSettings();

    this.addRibbonIcon('file-down', 'PDF-export · 精美导出', () => {
      new JXExportModal(this).open();
    });

    this.addCommand({
      id: 'export-pdf',
      name: '导出当前笔记为精美 PDF',
      callback: () => new JXExportModal(this).open(),
    });

    this.addCommand({
      id: 'export-pdf-quick',
      name: '快速导出（跳过弹窗，使用默认预设）',
      callback: () =>
        this.runExport('pdf', {
          preset: this.settings.preset,
          cover: this.settings.cover,
          toc: this.settings.toc,
          header: this.settings.header,
          pageNumbers: this.settings.pageNumbers,
        }),
    });

    this.addSettingTab(new JXSettingTab(this.app, this));
  }

  async loadSettings() {
    this.settings = Object.assign({}, DEFAULT_SETTINGS, await this.loadData());
  }

  saveSettings() {
    return this.saveData(this.settings);
  }

  get pluginDir() {
    const base =
      (this.app.vault.adapter && this.app.vault.adapter.basePath) || '';
    return path.join(base, this.manifest.dir || 'j-studio-export');
  }

  /* ============ 导出主流程 ============ */

  async runExport(kind, opts) {
    const file = this.app.workspace.getActiveFile();
    if (!file || file.extension !== 'md') {
      new Notice('请先打开一篇 Markdown 笔记');
      return;
    }

    const notice = new Notice('正在渲染笔记…', 0);
    let htmlOut = null;
    try {
      /* 1. 渲染为与预览一致的 DOM */
      const rendered = await this.renderNote(file);

      /* 2. 元数据（标题/作者/日期/栏目线） */
      const meta = this.buildMeta(file, rendered.frontmatter, rendered.firstH1);

      /* 3. 组装独立 HTML 文档 */
      htmlOut = await this.buildDocument(rendered, meta, opts, kind === 'html');

      /* 4a. HTML 导出：直接写自包含文件 */
      if (kind === 'html') {
        const outPath = await this.saveOutput('html', htmlOut, file);
        if (outPath) new Notice(`已导出 HTML：${path.basename(outPath)}`);
        return;
      }

      /* 4b. PDF：临时 HTML → 隐藏窗口 → Paged.js → 打印 */
      notice.setMessage('正在分页排版…');
      const tmpHtml = path.join(this.pluginDir, 'jx-tmp-export.html');
      fs.writeFileSync(tmpHtml, htmlOut, 'utf8');
      try {
        const pdfBuffer = await this.htmlToPdf(tmpHtml);
        const outPath = await this.saveOutput('pdf', pdfBuffer, file);
        if (outPath) new Notice(`已导出 PDF：${path.basename(outPath)}`);
      } finally {
        try {
          fs.unlinkSync(tmpHtml);
        } catch (e) {
          /* noop */
        }
      }
    } catch (err) {
      console.error('[j-studio-export]', err);
      if (
        err &&
        (err.message === 'NO_REMOTE' || err.message === 'PAGEDJS_FAILED') &&
        htmlOut
      ) {
        await this.fallbackHtml(htmlOut, file);
      } else {
        new Notice(`导出失败：${err.message || err}`, 6000);
      }
    } finally {
      notice.hide();
    }
  }

  /* ============ 渲染 ============ */

  async renderNote(file) {
    const raw = await this.app.vault.read(file);
    const component = new Component();
    component.load();

    const host = document.createElement('div');
    host.className = 'markdown-preview-view markdown-rendered jx-render-host';
    // 挂到屏幕外，让 Mermaid / Dataview / Excalidraw 等完成真实渲染
    host.style.cssText =
      'position:fixed;left:-99999px;top:0;width:760px;padding:24px;box-sizing:border-box;';
    document.body.appendChild(host);

    try {
      await MarkdownRenderer.render(
        this.app,
        raw,
        host,
        file.path,
        component
      );

      /* 等图片加载完（内嵌需要真实尺寸与内容） */
      const imgs = Array.from(host.querySelectorAll('img'));
      await Promise.race([
        Promise.all(
          imgs.map((im) =>
            im.complete
              ? Promise.resolve()
              : new Promise((res) => {
                  im.onload = im.onerror = res;
                })
          )
        ),
        sleep(8000),
      ]);
      await sleep(400); // 留给异步后处理器收尾

      this.embedImages(host);
      this.normalizeCallouts(host);
      const { headings, firstH1 } = this.collectHeadings(host);

      return {
        html: host.innerHTML,
        headings,
        firstH1,
        frontmatter: this.parseFrontmatter(raw),
      };
    } finally {
      host.remove();
      component.unload();
    }
  }

  /* 把 app:// 图片替换为 base64，供独立窗口使用 */
  embedImages(host) {
    const basePath =
      (this.app.vault.adapter && this.app.vault.adapter.basePath) || '';
    host.querySelectorAll('img').forEach((img) => {
      const src = img.getAttribute('src') || '';
      let rel = null;
      const m = src.match(/^app:\/\/[^/]+\/(.+)$/);
      if (m) {
        const raw = m[1].split('?')[0];
        try {
          rel = decodeURIComponent(raw);
        } catch (e) {
          rel = raw;
        }
      }
      if (rel) {
        /* Obsidian 渲染出的 app:// 链接，host 之后接的是 URL 编码的
           "绝对路径"（如 E:/OneDrive/...），不能再与 basePath 拼接，
           否则会得到非法路径导致图片静默丢失；相对路径才需要拼 */
        const isAbs =
          /^[a-zA-Z]:[\\/]/.test(rel) ||
          rel.startsWith('\\\\') ||
          rel.startsWith('/');
        const abs = isAbs
          ? path.normalize(rel)
          : basePath
            ? path.join(basePath, rel)
            : null;
        if (!abs) return;
        try {
          if (fs.existsSync(abs)) {
            const b64 = fs.readFileSync(abs).toString('base64');
            img.setAttribute(
              'src',
              `data:${mimeOf(abs)};base64,${b64}`
            );
          }
        } catch (e) {
          /* 保留原样 */
        }
      }
      img.removeAttribute('srcset');
      img.removeAttribute('loading');
    });
  }

  /* Obsidian callout 的颜色变量统一为 "r, g, b" 三元组格式 */
  normalizeCallouts(host) {
    host.querySelectorAll('.callout').forEach((el) => {
      const style = el.getAttribute('style') || '';
      const m = style.match(/--callout-color:\s*(#[0-9a-fA-F]{3,8})/);
      if (m) {
        const triplet = hexToRgbTriplet(m[1]);
        if (triplet) {
          el.setAttribute(
            'style',
            style.replace(m[1], triplet)
          );
        }
      }
    });
  }

  /* 收集标题 → 目录锚点；顺带识别"首 H1 即文档标题"的情况 */
  collectHeadings(host) {
    const headings = [];
    let firstH1 = null;
    let idx = 0;
    host.querySelectorAll('h1, h2, h3, h4, h5, h6').forEach((el) => {
      if (el.closest('.callout')) return; // callout 内的标题不进目录
      const level = Number(el.tagName[1]);
      const id = `jx-h-${idx++}`;
      el.setAttribute('id', id);
      const text = (el.textContent || '').trim();
      if (!text) return;
      if (level === 1 && firstH1 === null) firstH1 = text;
      headings.push({ level, text, id });
    });
    return { headings, firstH1 };
  }

  parseFrontmatter(raw) {
    const fm = {};
    const m = raw.match(/^---\r?\n([\s\S]*?)\r?\n---/);
    if (!m) return fm;
    for (const line of m[1].split(/\r?\n/)) {
      const kv = line.match(/^([A-Za-z0-9_-]+)\s*:\s*(.*)$/);
      if (kv) fm[kv[1].toLowerCase()] = kv[2].trim().replace(/^["']|["']$/g, '');
    }
    return fm;
  }

  /* ============ 元数据 ============ */

  buildMeta(file, fm, firstH1) {
    const fmTitle = fm.title || fm['标题'];
    const title = fmTitle || firstH1 || file.basename;

    const subtitle =
      fm.subtitle || fm.subject || fm.description || fm['副标题'] || '';

    const kicker =
      fm.kicker ||
      fm['栏目'] ||
      (file.parent && file.parent.path
        ? file.parent.path.replace(/[\\\/]+/g, ' · ')
        : '');

    const author = fm.author || fm['作者'] || this.settings.author || '';

    let dateStr = '';
    const raw = fm.date || fm['日期'];
    const d = raw ? new Date(raw) : new Date();
    if (!isNaN(d.getTime())) {
      dateStr = `${d.getFullYear()} 年 ${d.getMonth() + 1} 月 ${d.getDate()} 日`;
    } else {
      dateStr = raw;
    }

    return { title, subtitle, kicker, author, dateStr };
  }

  /* ============ 样式收集 ============ */

  async collectStyles() {
    let css = '';
    for (const sheet of Array.from(document.styleSheets)) {
      const node = sheet.ownerNode;
      try {
        if (node && node.tagName === 'STYLE') {
          css += node.textContent + '\n';
        } else {
          css += Array.from(sheet.cssRules).map((r) => r.cssText).join('\n') + '\n';
        }
      } catch (e) {
        const href = node && node.href;
        if (href) {
          try {
            css += (await (await fetch(href)).text()) + '\n';
          } catch (e2) {
            /* 跳过跨域样式 */
          }
        }
      }
    }
    /* 消毒：去掉会让 Paged.js 崩溃的选择器与 @media print 块 */
    return sanitizeCssForPagedjs(css);
  }

  /* 用 DOMParser 安全地把与标题重复的首个 H1 标记隐藏（避免拼出重复 class 属性） */
  hideDuplicateTitle(html, title) {
    try {
      const doc = new DOMParser().parseFromString(html, 'text/html');
      const h1 = [...doc.body.querySelectorAll('h1')].find(
        (h) => !h.closest('.callout')
      );
      if (h1 && (h1.textContent || '').trim() === title) {
        h1.classList.add('jx-title-hidden');
        return doc.body.innerHTML;
      }
    } catch (e) {
      /* 解析失败则原样返回 */
    }
    return html;
  }

  /* ============ 文档组装 ============ */

  async buildDocument(rendered, meta, opts, inlineVendor) {
    const dir = this.pluginDir;
    const readPreset = (name) => {
      /* 开发态：优先读真实文件（改 CSS 即改即测）；
         商店安装：目录不存在，回退到内嵌副本 */
      try {
        return fs.readFileSync(path.join(dir, 'presets', name), 'utf8');
      } catch (e) {
        return embeddedPresetText(name);
      }
    };

    const isReport = opts.preset === 'report';
    const useCover = isReport && opts.cover;
    const useToc =
      isReport && opts.toc && rendered.headings.some((h) => h.level <= 2);

    /* 与文档标题重复的首个 H1 隐藏（报告模式，标题已在封面呈现） */
    let contentHtml = rendered.html;
    if (isReport && rendered.firstH1 && rendered.firstH1 === meta.title) {
      contentHtml = this.hideDuplicateTitle(contentHtml, meta.title);
    }

    const parts = [];
    if (useCover) {
      parts.push(
        `<section class="jx-cover">
  <div class="jx-cover-top">
    <div class="jx-cover-bar"></div>
    <div class="jx-cover-kicker">${escapeHtml(meta.kicker || 'J-STUDIO')}</div>
  </div>
  <div class="jx-cover-mid">
    <h1 class="jx-cover-title">${escapeHtml(meta.title)}</h1>
    ${meta.subtitle ? `<p class="jx-cover-sub">${escapeHtml(meta.subtitle)}</p>` : ''}
  </div>
  <div class="jx-cover-meta">
    <div>
      ${meta.author ? `<div class="jx-cover-authorline">${escapeHtml(meta.author)}</div>` : ''}
      <div class="jx-cover-date">${escapeHtml(meta.dateStr)}</div>
    </div>
    <div class="jx-cover-brand">${escapeHtml(this.settings.brand || 'J · STUDIO')}</div>
  </div>
</section>`
      );
    }

    if (useToc) {
      const items = rendered.headings
        .filter((h) => h.level <= 3)
        .map(
          (h) =>
            `<div class="jx-toc-item l${h.level}"><a href="#${h.id}"><span class="jx-toc-text">${escapeHtml(h.text)}</span><span class="jx-toc-dots"></span></a></div>`
        )
        .join('\n');
      parts.push(
        `<nav class="jx-toc">
  <div class="jx-toc-title">目 录</div>
  ${items}
</nav>`
      );
    }

    parts.push(
      `<main class="markdown-preview-view markdown-rendered jx-content jx-body">\n${contentHtml}\n</main>`
    );

    /* 开关覆盖（后置于预设，级联生效） */
    let toggleCss = '';
    if (isReport) {
      if (!opts.header)
        toggleCss += '@page { @top-center { content: none; border: none; } }\n';
      if (!opts.pageNumbers)
        toggleCss += '@page { @bottom-center { content: none; } }\n';
      if (!opts.cover) toggleCss += '.jx-cover { display: none; }\n';
      if (!opts.toc) toggleCss += '.jx-toc { display: none; }\n';
    } else {
      if (!opts.pageNumbers)
        toggleCss += '@page { @bottom-center { content: none; } }\n';
    }

    const alwaysCss = `
* { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.jx-export audio, .jx-export video, .jx-export iframe { display: none !important; }
`;

    const appCss = await this.collectStyles();
    const baseCss = readPreset('_base.css');
    const presetCss = readPreset(`${opts.preset}.css`);
    const customCss = this.settings.customCss || '';

    let vendorScript = '';
    try {
      /* 统一内联分页引擎：开发态读 vendor/ 真实文件，
         商店安装回退到内嵌副本。内联后导出不再依赖
         临时 HTML 与 vendor/ 的相对位置，任何机器都可用 */
      let js = '';
      const vendorPath = path.join(dir, 'vendor', 'paged.polyfill.js');
      if (fs.existsSync(vendorPath)) {
        js = fs.readFileSync(vendorPath, 'utf8');
      } else {
        js = decodeEmbeddedText(EMBEDDED_ASSETS.pagedPolyfillB64);
      }
      if (js) vendorScript = `<script>\n${js}\n</script>`;
    } catch (e) {
      vendorScript = '';
    }

    return `<!DOCTYPE html>
<html class="theme-light">
<head>
<meta charset="utf-8">
<title>${escapeHtml(meta.title)}</title>
<style>/* ---- 收集自 Obsidian 的应用与插件样式（仅屏幕态生效：
     供 Paged.js 分页测量保真；打印态由下方插件排版 CSS 接管，
     规避 app.css 的 html/body height:100% 等打印态怪癖） ---- */
@media screen {
${appCss}
}
</style>
<style>/* ---- PDF-export 排版基础 ---- */
${baseCss}
</style>
<style>/* ---- 预设：${opts.preset} ---- */
${presetCss}
</style>
<style>/* ---- 开关与自定义 ---- */
${alwaysCss}
${toggleCss}
${customCss}
</style>
<script>
window.PagedConfig = {
  auto: true,
  after: function () {
    document.fonts.ready.then(function () { window.__jxPagedDone = true; });
  }
};
</script>
${vendorScript}
</head>
<body class="jx-export theme-light">
${parts.join('\n')}
</body>
</html>`;
  }

  /* ============ HTML → PDF ============ */

  async htmlToPdf(htmlPath) {
    const remote = electronRemote();
    if (!remote || !remote.BrowserWindow) {
      throw new Error('NO_REMOTE');
    }
    const { BrowserWindow } = remote;
    const win = new BrowserWindow({
      show: false,
      width: 1000,
      height: 1400,
    });
    // 导出窗口的报错转发到主控制台，便于远程排查
    try {
      win.webContents.on('console-message', (_e, _lvl, message) => {
        if (message && /[error|warn]/i.test(message)) {
          console.log('[jx-export-window]', message);
        }
      });
    } catch (e) {
      /* noop */
    }
    try {
      await win.loadURL(fileUrl(htmlPath));
      const ok = await this.waitPaged(win, 60000);
      // 分页引擎是否真的产出了页面（防止 CSS 解析意外导致整页直出）
      const pageCount = await win.webContents
        .executeJavaScript('document.querySelectorAll(".pagedjs_page").length')
        .catch(() => 0);
      if (!ok && !pageCount) {
        throw new Error('PAGEDJS_FAILED');
      }
      if (!ok) {
        new Notice('分页引擎未在限时内完成，按当前进度输出');
      }
      await sleep(300);
      return await win.webContents.printToPDF({
        printBackground: true,
        preferCSSPageSize: true,
        margins: { top: 0, bottom: 0, left: 0, right: 0 },
      });
    } finally {
      try {
        win.destroy();
      } catch (e) {
        /* noop */
      }
    }
  }

  async waitPaged(win, timeoutMs) {
    const t0 = Date.now();
    while (Date.now() - t0 < timeoutMs) {
      try {
        const done = await win.webContents.executeJavaScript(
          'window.__jxPagedDone === true'
        );
        if (done) return true;
      } catch (e) {
        /* 页面导航中，重试 */
      }
      await sleep(250);
    }
    return false;
  }

  /* ============ 输出保存 ============ */

  async saveOutput(kind, data, file) {
    const remote = electronRemote();
    const basePath =
      (this.app.vault.adapter && this.app.vault.adapter.basePath) || '';
    const noteDir = file.parent ? file.parent.path : '';
    const defaultName =
      kind === 'pdf'
        ? `${file.basename}.pdf`
        : `${file.basename}-export.html`;
    const defaultDirAbs = path.join(basePath, noteDir, defaultName);

    let target = null;
    if (this.settings.outputMode === 'note-folder') {
      target = defaultDirAbs;
    } else {
      if (!remote || !remote.dialog) throw new Error('NO_REMOTE');
      const r = await remote.dialog.showSaveDialog({
        defaultPath: defaultDirAbs,
        filters:
          kind === 'pdf'
            ? [{ name: 'PDF', extensions: ['pdf'] }]
            : [{ name: 'HTML', extensions: ['html'] }],
      });
      if (r.canceled || !r.filePath) return null;
      target = r.filePath;
    }

    if (kind === 'pdf') {
      fs.writeFileSync(target, data);
    } else {
      fs.writeFileSync(target, data, 'utf8');
    }

    if (this.settings.openAfter) {
      try {
        if (remote && remote.shell) remote.shell.openPath(target);
      } catch (e) {
        /* noop */
      }
    }
    return target;
  }

  /* ============ 无 Electron remote 的兜底 ============ */

  async fallbackHtml(html, file) {
    const basePath =
      (this.app.vault.adapter && this.app.vault.adapter.basePath) || '';
    const out = path.join(
      basePath,
      file.parent ? file.parent.path : '',
      `${file.basename}-export.html`
    );
    fs.writeFileSync(out, html, 'utf8');
    new Notice(
      '当前环境不支持静默打印，已生成独立 HTML。请在浏览器打开后 Ctrl+P 选择"另存为 PDF"，分页样式已内置。',
      10000
    );
  }
};
